import openpyxl
wb = openpyxl.load_workbook('3_59055_answer_template_4319_input.xlsx')
ws = wb['Sheet1']
for r in range(1, 20):
    infos=[]
    for c in range(1, 14):
        cell = ws.cell(r,c)
        v = cell.value
        # fill
        fill = cell.fill
        ft = fill.fill_type
        fg = fill.fgColor
        try:
            fgrgb = fg.rgb
        except Exception as e:
            fgrgb = 'ERR:'+str(e)
        try:
            bgrgb = fill.bgColor.rgb
        except Exception as e:
            bgrgb = 'ERR:'+str(e)
        b = (cell.border.left.style, cell.border.right.style, cell.border.top.style, cell.border.bottom.style)
        num = cell.number_format
        if v is not None or ft or any(x for x in b) or num!='General':
            infos.append(f'{openpyxl.utils.get_column_letter(c)}{r}: v={v!r} filltype={ft} fg={fgrgb} bg={bgrgb} num={num!r} b={b}')
    if infos:
        print('ROW', r)
        for i in infos:
            print('   ', i)
"

